import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, color } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new THREE.Group();

  // ─────────────────────────────────────────────────────────────────────────────
  // 1. STAGE: Gradient backdrop plane
  // ─────────────────────────────────────────────────────────────────────────────
  const stageGeom = new THREE.PlaneGeometry(7, 6);
  const stageMaterial = new MeshBasicNodeMaterial();

  // Gradient from surface (#0b0b10) to ink (#16161d)
  const gradientNode = mix(
    color(new THREE.Color('#0b0b10')),
    color(new THREE.Color('#16161d')),
    uv().y
  );
  stageMaterial.colorNode = gradientNode;

  const stagePlane = new THREE.Mesh(stageGeom, stageMaterial);
  stagePlane.position.z = -2.5;
  group.add(stagePlane);

  // ─────────────────────────────────────────────────────────────────────────────
  // 2. HERO TEXTURED PLANE
  // ─────────────────────────────────────────────────────────────────────────────
  const cardGeom = new THREE.PlaneGeometry(2, 1.25);
  const cardMaterial = new MeshBasicNodeMaterial();

  const cardPlane = new THREE.Mesh(cardGeom, cardMaterial);
  cardPlane.position.set(3.2, 1, 0.06);
  cardPlane.rotation.order = 'XYZ';

  group.add(cardPlane);

  // Load texture and apply
  ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    tex.colorSpace = THREE.SRGBColorSpace;
    cardMaterial.map = tex;
    cardMaterial.needsUpdate = true;
  });

  // ─────────────────────────────────────────────────────────────────────────────
  // 3. HEADLINE TEXT: "Collection 3"
  // ─────────────────────────────────────────────────────────────────────────────
  const textContent = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  let headlineText = 'Collection 3';

  for (const item of textContent) {
    if (item.role === 'headline' && item.text) {
      headlineText = String(item.text);
      break;
    }
  }

  const headline = ctx.fontAtlas.createText(headlineText, {
    fontSize: 39,
    color: '#e8ecf2',
    align: 'center',
    maxWidthPx: 400
  });
  headline.position.set(3.2, 0.35, 0.5);
  group.add(headline);

  // ─────────────────────────────────────────────────────────────────────────────
  // 4. CONTACT-SHADOW PLANE
  // ─────────────────────────────────────────────────────────────────────────────
  const shadowGeom = new THREE.PlaneGeometry(3.2, 1.6);
  const shadowMaterial = new MeshBasicNodeMaterial();
  shadowMaterial.transparent = true;
  shadowMaterial.colorNode = mix(
    color(new THREE.Color('#000000')),
    color(new THREE.Color('#000000')),
    uv().y
  );
  shadowMaterial.opacity = 0.5;

  const shadowPlane = new THREE.Mesh(shadowGeom, shadowMaterial);
  shadowPlane.position.set(3.2, -0.4, -0.1);
  group.add(shadowPlane);

  // ─────────────────────────────────────────────────────────────────────────────
  // 5. CLEANUP & HANDLERS
  // ─────────────────────────────────────────────────────────────────────────────
  group.userData.cleanup = () => {
    cardGeom.dispose();
    cardMaterial.dispose();
    stageGeom.dispose();
    stageMaterial.dispose();
    shadowGeom.dispose();
    shadowMaterial.dispose();
    gsap.killTweensOf([cardPlane.position, cardPlane.scale, headline.position]);
  };

  group.userData.handlers = {};

  return group;
}
